    const url = `https://${name}.sprites.run`;
    for (let i = 0; i < 12; i++) {
      try {
        const p = await fetch(url, { signal: AbortSignal.timeout(4000) });
        if (p.ok) return { name, url };
      } catch {}
      await new Promise((r) => setTimeout(r, 1000));
    }
    return { name, url };
  });
